PRAGMA foreign_keys = OFF;

BEGIN TRANSACTION;
CREATE TABLE "account" ("account_id" TEXT PRIMARY KEY NOT NULL, "account_name" TEXT, "industry" TEXT, "account_status" TEXT, "territory_id" TEXT, "created_at" TEXT, FOREIGN KEY ("territory_id") REFERENCES "territory" ("territory_id"));
CREATE TABLE "activity" ("activity_id" TEXT PRIMARY KEY NOT NULL, "opportunity_id" TEXT, "rep_id" TEXT, "activity_type" TEXT, "activity_date" TEXT, "subject" TEXT, "outcome" TEXT, FOREIGN KEY ("opportunity_id") REFERENCES "opportunity" ("opportunity_id"), FOREIGN KEY ("rep_id") REFERENCES "sales_rep" ("rep_id"));
CREATE TABLE "forecast_snapshot" ("forecast_snapshot_id" TEXT PRIMARY KEY NOT NULL, "snapshot_date" TEXT, "opportunity_id" TEXT, "stage_id" TEXT, "amount" REAL, "expected_close_date" TEXT, "last_activity_date" TEXT, "stale_days" INTEGER, "is_stale" INTEGER, FOREIGN KEY ("opportunity_id") REFERENCES "opportunity" ("opportunity_id"), FOREIGN KEY ("stage_id") REFERENCES "stage" ("stage_id"));
CREATE TABLE "historical_booking" ("booking_id" TEXT PRIMARY KEY NOT NULL, "opportunity_id" TEXT, "account_id" TEXT, "rep_id" TEXT, "booking_date" TEXT, "booking_amount" REAL, "currency_code" TEXT, FOREIGN KEY ("opportunity_id") REFERENCES "opportunity" ("opportunity_id"), FOREIGN KEY ("account_id") REFERENCES "account" ("account_id"), FOREIGN KEY ("rep_id") REFERENCES "sales_rep" ("rep_id"));
CREATE TABLE "opportunity" ("opportunity_id" TEXT PRIMARY KEY NOT NULL, "opportunity_name" TEXT, "account_id" TEXT, "owner_rep_id" TEXT, "territory_id" TEXT, "source_opportunity_id" TEXT, "created_date" TEXT, "expected_close_date" TEXT, "amount" REAL, "currency_code" TEXT, "product" TEXT, "current_stage" TEXT, "closed_date" TEXT, "outcome" TEXT, FOREIGN KEY ("account_id") REFERENCES "account" ("account_id"), FOREIGN KEY ("owner_rep_id") REFERENCES "sales_rep" ("rep_id"), FOREIGN KEY ("territory_id") REFERENCES "territory" ("territory_id"), FOREIGN KEY ("source_opportunity_id") REFERENCES "opportunity" ("opportunity_id"), FOREIGN KEY ("current_stage") REFERENCES "stage" ("stage_name"));
CREATE TABLE "quota" ("quota_id" TEXT PRIMARY KEY NOT NULL, "rep_id" TEXT, "fiscal_quarter" TEXT, "quota_amount" REAL, "currency_code" TEXT, FOREIGN KEY ("rep_id") REFERENCES "sales_rep" ("rep_id"));
CREATE TABLE "rep_territory_assignment" ("assignment_id" TEXT PRIMARY KEY NOT NULL, "rep_id" TEXT, "territory_id" TEXT, "effective_from" TEXT, "effective_to" TEXT, FOREIGN KEY ("rep_id") REFERENCES "sales_rep" ("rep_id"), FOREIGN KEY ("territory_id") REFERENCES "territory" ("territory_id"));
CREATE TABLE "sales_rep" ("rep_id" TEXT PRIMARY KEY NOT NULL, "rep_name" TEXT, "email" TEXT, "hire_date" TEXT, "employment_status" TEXT, "created_at" TEXT);
CREATE TABLE "stage" ("stage_id" TEXT PRIMARY KEY NOT NULL, "stage_name" TEXT UNIQUE, "stage_order" INTEGER, "default_probability" REAL, "is_closed_stage" INTEGER);
CREATE TABLE "stage_history" ("stage_history_id" TEXT PRIMARY KEY NOT NULL, "opportunity_id" TEXT, "from_stage_id" TEXT, "to_stage_id" TEXT, "changed_by_rep_id" TEXT, "changed_at" TEXT, "reason" TEXT, "event_sequence" INTEGER, FOREIGN KEY ("opportunity_id") REFERENCES "opportunity" ("opportunity_id"), FOREIGN KEY ("from_stage_id") REFERENCES "stage" ("stage_id"), FOREIGN KEY ("to_stage_id") REFERENCES "stage" ("stage_id"), FOREIGN KEY ("changed_by_rep_id") REFERENCES "sales_rep" ("rep_id"));
CREATE TABLE "territory" ("territory_id" TEXT PRIMARY KEY NOT NULL, "territory_name" TEXT, "region" TEXT, "country_code" TEXT, "created_at" TEXT, "status" TEXT);
CREATE INDEX "idx_account_territory_id" ON "account" ("territory_id");
CREATE INDEX "idx_rep_territory_assignment_rep_id" ON "rep_territory_assignment" ("rep_id");
CREATE INDEX "idx_rep_territory_assignment_territory_id" ON "rep_territory_assignment" ("territory_id");
CREATE INDEX "idx_opportunity_account_id" ON "opportunity" ("account_id");
CREATE INDEX "idx_opportunity_owner_rep_id" ON "opportunity" ("owner_rep_id");
CREATE INDEX "idx_opportunity_territory_id" ON "opportunity" ("territory_id");
CREATE INDEX "idx_opportunity_source_opportunity_id" ON "opportunity" ("source_opportunity_id");
CREATE INDEX "idx_opportunity_current_stage" ON "opportunity" ("current_stage");
CREATE INDEX "idx_stage_history_opportunity_id" ON "stage_history" ("opportunity_id");
CREATE INDEX "idx_stage_history_from_stage_id" ON "stage_history" ("from_stage_id");
CREATE INDEX "idx_stage_history_to_stage_id" ON "stage_history" ("to_stage_id");
CREATE INDEX "idx_stage_history_changed_by_rep_id" ON "stage_history" ("changed_by_rep_id");
CREATE INDEX "idx_activity_opportunity_id" ON "activity" ("opportunity_id");
CREATE INDEX "idx_activity_rep_id" ON "activity" ("rep_id");
CREATE INDEX "idx_quota_rep_id" ON "quota" ("rep_id");
CREATE INDEX "idx_historical_booking_opportunity_id" ON "historical_booking" ("opportunity_id");
CREATE INDEX "idx_historical_booking_account_id" ON "historical_booking" ("account_id");
CREATE INDEX "idx_historical_booking_rep_id" ON "historical_booking" ("rep_id");
CREATE INDEX "idx_forecast_snapshot_opportunity_id" ON "forecast_snapshot" ("opportunity_id");
CREATE INDEX "idx_forecast_snapshot_stage_id" ON "forecast_snapshot" ("stage_id");
COMMIT;

PRAGMA foreign_keys = ON;
